SELECT * FROM logs WHERE Channel='Microsoft-Windows-Sysmon/Operational' AND (EventID=10 AND ((TargetImage LIKE '%\\lsass.exe' ESCAPE '\' AND (GrantedAccess LIKE '%0x1038%' ESCAPE '\' OR GrantedAccess LIKE '%0x1438%' ESCAPE '\' OR GrantedAccess LIKE '%0x143a%' ESCAPE '\' OR GrantedAccess LIKE '%0x1fffff%' ESCAPE '\') AND (CallTrace LIKE '%dbgcore.dll%' ESCAPE '\' OR CallTrace LIKE '%dbghelp.dll%' ESCAPE '\' OR CallTrace LIKE '%kernel32.dll%' ESCAPE '\' OR CallTrace LIKE '%kernelbase.dll%' ESCAPE '\' OR CallTrace LIKE '%ntdll.dll%' ESCAPE '\')) AND (NOT COALESCE((SourceUser LIKE '%AUTHORI%' ESCAPE '\' OR SourceUser LIKE '%AUTORI%' ESCAPE '\'), 0)) AND (NOT COALESCE((((CallTrace LIKE '%:\\Windows\\Temp\\asgard2-agent\\%' ESCAPE '\' AND CallTrace LIKE '%\\thor\\thor64.exe+%' ESCAPE '\' AND CallTrace LIKE '%|UNKNOWN(%' ESCAPE '\') AND GrantedAccess='0x103800') OR (SourceImage LIKE '%:\\Windows\\Sysmon64.exe' ESCAPE '\' OR SourceImage LIKE '%:\\Windows\\Sysmon64a.exe' ESCAPE '\')), 0))))
